Rule.fixtext:
Run the following command: # grep -Pl -- ' pam_pwquality\.so\h+([^#
]+\h+)?(minclass|[dulo]credit) ' /usr/share/pam-configs/* Edit any returned files and remove the minclass, dcredit, ucredit, lcredit, and ocredit arguments from the pam_pwquality.so line(s) Create or modify a file ending in.conf in the /etc/security/pwquality.conf.d/ directory or the file /etc/security/pwquality.conf and add or modify the following line(s) to set complexity according to local site policy: • minclass = _N_ • dcredit = _N_ # Value should be either 0 or a number proceeded by a minus ( - ) symbol • ucredit = -1 # Value should be either 0 or a number proceeded by a minus ( -) symbol • ocredit = -1 # Value should be either 0 or a number proceeded by a minus ( -) symbol • lcredit = -1 # Value should be either 0 or a number proceeded by a minus ( -) symbol Example 1 - Set minclass = 3: #!/usr/bin/env bash { sed -ri 's/^\s*minclass\s*=/# &/' /etc/security/pwquality.conf sed -ri 's/^\s*[dulo]credit\s*=/# &/' /etc/security/pwquality.conf [ ! -d /etc/security/pwquality.conf.d/ ] && mkdir /etc/security/pwquality.conf.d/ printf '
%s' "minclass = 3" > /etc/security/pwquality.conf.d/50- pwcomplexity.conf } Example 2 - set dcredit = -1, ucredit = -1, and lcredit = -1: #!/usr/bin/env bash { sed -ri 's/^\s*minclass\s*=/# &/' /etc/security/pwquality.conf sed -ri 's/^\s*[dulo]credit\s*=/# &/' /etc/security/pwquality.conf [ ! -d /etc/security/pwquality.conf.d/ ] && mkdir /etc/security/pwquality.conf.d/ printf '%s
' "dcredit = -1" "ucredit = -1" "lcredit = -1" > /etc/security/pwquality.conf.d/50-pwcomplexity.conf }

Edit or add the following line in a *.conf file in /etc/security/pwquality.conf.d or in /etc/security/pwquality.conf:
Example:
#!/usr/bin/env bash
{
[ ! -d /etc/security/pwquality.conf.d/ ] && mkdir
/etc/security/pwquality.conf.d/
printf '\n%s\n' "enforce_for_root" > /etc/security/pwquality.conf.d/50-
pwroot.conf
}

check.check-content:
Run the following script to verify that TMOUT is configured to: include a timeout of no more than 900 seconds, to be readonly, to be exported, and is not being changed to a longer timeout. #!/usr/bin/env bash { a_output=(); a_output2=(); l_tmout_set="900" f_tmout_read_chk() { a_out=(); a_out2=() l_tmout_readonly="$(grep -P -- '^\h*(typeset\h\- xr\hTMOUT=\d+|([^#
]+)? readonly\h+TMOUT )' "$l_file")" l_tmout_export="$(grep -P -- '^\h*(typeset\h\- xr\hTMOUT=\d+|([^#
]+)? export ([^#
]+ )?TMOUT )' "$l_file")" if [ -n "$l_tmout_readonly" ]; then a_out+=(" - Readonly is set as: "$l_tmout_readonly" in: "$l_file"") else a_out2+=(" - Readonly is not set in: "$l_file"") fi if [ -n "$l_tmout_export" ]; then a_out+=(" - Export is set as: "$l_tmout_export" in: "$l_file"") else a_out2+=(" - Export is not set in: "$l_file"") fi } while IFS= read -r l_file; do l_tmout_value="$(grep -Po -- '^([^#
]+)? TMOUT=\d+ ' "$l_file" | awk -F= '{print $2}')" f_tmout_read_chk if [ -n "$l_tmout_value" ]; then if [[ "$l_tmout_value" -le "$l_tmout_set" && "$l_tmout_value" -gt "0" ]]; then a_output+=(" - TMOUT is set to: "$l_tmout_value" in: "$l_file"") [ "${#a_out[@]}" -gt 0 ] && a_output+=("${a_out[@]}") [ "${#a_out2[@]}" -gt 0 ] && a_output2+=("${a_out[@]}") fi if [[ "$l_tmout_value" -gt "$l_tmout_set" || "$l_tmout_value" -le "0" ]]; then a_output2+=(" - TMOUT is incorrectly set to: "$l_tmout_value" in: "$l_file"") [ "${#a_out[@]}" -gt 0 ] && a_output2+=(" ** Incorrect TMOUT value **" "${a_out[@]}") [ "${#a_out2[@]}" -gt 0 ] && a_output2+=("${a_out2[@]}") fi else [ "${#a_out[@]}" -gt 0 ] && a_output2+=(" - TMOUT is not set" "${a_out[@]}") [ "${#a_out2[@]}" -gt 0 ] && a_output2+=(" - TMOUT is not set" "${a_out2[@]}") fi done < <(grep -Pls -- '^([^#
]+)? TMOUT ' /etc/*bashrc /etc/profile /etc/profile.d/*.sh) [[ "${#a_output[@]}" -le 0 && "${#a_output2[@]}" -le 0 ]] && a_output2+=(" - TMOUT is not configured") if [ "${#a_output2[@]}" -le 0 ]; then printf '%s
' "" "- Audit Result:" " ** PASS **" "${a_output[@]}" else printf '%s
' "" "- Audit Result:" " ** FAIL **" " * Reasons for audit failure *" "${a_output2[@]}" "" [ "${#a_output[@]}" -gt 0 ] && printf '%s
' "- Correctly set:" "${a_output[@]}" fi } Note: If TMOUT is set as readonly through readonly TMOUT and/or typeset -xr in more than once, you will receive an error message when logging into a terminal session or connecting with openSSH. It is recommended that TMOUT be set only once in only one file.

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_uid; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate UID: \"$l_uid\" Users: \"$(awk -F: '($3 == n) {
print $1 }' n=$l_uid /etc/passwd | xargs)\""
fi
done < <(cut -f3 -d":" /etc/passwd | sort -n | uniq -c)
}

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_gid; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate GID: \"$l_gid\" Groups: \"$(awk -F: '($3 == n) {
print $1 }' n=$l_gid /etc/group | xargs)\""
fi
done < <(cut -f3 -d":" /etc/group | sort -n | uniq -c)
}

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_user; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate User: \"$l_user\" Users: \"$(awk -F: '($1 == n) {
print $1 }' n=$l_user /etc/passwd | xargs)\""
fi
done < <(cut -f1 -d":" /etc/passwd | sort -n | uniq -c)
}

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_group; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate Group: \"$l_group\" Groups: \"$(awk -F: '($1 ==
n) { print $1 }' n=$l_group /etc/group | xargs)\""
fi
done < <(cut -f1 -d":" /etc/group | sort -n | uniq -c)
}
